set local role authenticated;
select pg_temp.fails($q$select pg_temp.declare_image(gen_random_uuid(),null,'dddddddd-dddd-4ddd-8ddd-000000000007',repeat('e',64))$q$,'IMAGE_RIGHTS_REQUIRED','self declaration cannot revive revoked representation');
select pg_temp.ok(public.resolve_memory_image_preview((current_setting('decl.rep')::jsonb->>'id')::uuid,'full') is null,'representation revocation closes preview');
reset role;
update private.memory_publication_settings set general_publication_policy_revision='UNCONFIGURED';
set local role authenticated;
select pg_temp.ok(public.resolve_memory_image_preview((current_setting('decl.asset')::jsonb->>'id')::uuid,'full') is null,'policy rollback closes self-declared original');
reset role;
update private.memory_publication_settings set general_publication_policy_revision='TEST_DECLARED';
update private.memory_public_image_rights set revoked_at=now() where asset_id=current_setting('test.source')::uuid;
set local role authenticated;
select pg_temp.fails('select pg_temp.declare_image()','IMAGE_RIGHTS_REQUIRED','self declaration cannot revive revoked source');
