select pg_temp.ok(public.resolve_memory_public_image((current_setting('decl.preview')::jsonb->>'id')::uuid,(current_setting('decl.asset')::jsonb->>'id')::uuid,'full') is null,'source withdrawal closes already published image');
reset role;
select pg_temp.ok((select row_to_json(a)::text=current_setting('decl.source_before') from public.memory_visual_assets a where id=current_setting('test.source')::uuid),'declaration never changes private source metadata or bytes');
select pg_temp.ok(not has_function_privilege('anon','public.reserve_memory_declared_public_asset(uuid,bigint,uuid,text,text,uuid,text)','execute') and not has_table_privilege('authenticated','private.memory_public_image_rights','insert'),'no anonymous declaration or direct rights-table writes');
select count(*)-current_setting('decl.start')::int as passed_declaration_assertions from assertions;
